5	import { readFile, writeFile } from 'node:fs/promises';
6	import { dirname, join } from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	const dir = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'i18n', 'locales');
