1	/* ============================ Đi dạo: đầu vào từ bàn phím (thuần) ============================
2	   W/↑ tới, S/↓ lùi, A/← trái, D/→ phải theo hướng camera; chéo chuẩn hóa về độ dài 1; Shift chạy; Space nhảy.
3	   Nhảy ở đây chỉ phản ánh phím đang giữ: index.ts biến nó thành một lần nhảy mỗi lần bấm (stStep nhảy mỗi khung jump = true khi chạm đất).
4	   Không cấp phát (gọi mỗi khung). */
5	import type { StInput } from './motion';
6	
7	export function stInputFromKeys(keys: Set<string>, camYaw: number, out: StInput): StInput {
8	  let f = 0, r = 0;
9	  if (keys.has('w') || keys.has('arrowup')) f += 1;
10	  if (keys.has('s') || keys.has('arrowdown')) f -= 1;
11	  if (keys.has('d') || keys.has('arrowright')) r += 1;
12	  if (keys.has('a') || keys.has('arrowleft')) r -= 1;
13	  const len = Math.sqrt(f * f + r * r);
14	  if (len > 1) { f /= len; r /= len; }
15	  out.mz = f; out.mx = r; out.run = keys.has('shift'); out.jump = keys.has(' '); out.camYaw = camYaw;
16	  return out;
17	}
