1	/* ============================ Đi dạo: điều khiển cảm ứng ============================
2	   Ba con trỏ độc lập trên #stHud: cần gạt #stPad (ngón trái), vuốt #stLook (nửa phải, dưới các nút), nút #stJump; #stPhoto là nút bấm thường (cả máy tính).
3	   - Mỗi vùng chỉ theo con trỏ đã chạm vào nó (pointerId riêng + setPointerCapture), nên giữ cần gạt, vuốt camera và chạm Nhảy cùng lúc không lẫn nhau.
4	   - Nhảy theo cạnh: một lần chạm gọi jump() một lần (stStep nhảy lại ngay khi chạm đất nếu jump còn giữ).
5	   - Thả tay, pointercancel, lostpointercapture, blur, ẩn tab, xoay màn hình, đổi cỡ khung nhìn: reset() — cần gạt về giữa, nhân vật dừng (Review Focus 2).
6	   - read(out) chỉ ghi đè mx / mz / run khi cần gạt đang được giữ (cảm ứng ưu tiên phím); mỗi khung không cấp phát (D-018). */
7	import { CONFIG } from '../../config';
8	import { stStick } from './stick';
9	import type { StInput } from './motion';
10	
11	export interface StTouchHandlers { look(dxPx: number, dyPx: number): void; jump(): void; photo(): void; activity(): void }
12	
13	export function stTouchBind(root: HTMLElement, h: StTouchHandlers): { read(out: StInput): void; reset(): void } {
14	  const pad = root.querySelector<HTMLElement>('#stPad'), knob = root.querySelector<HTMLElement>('#stKnob');
15	  const look = root.querySelector<HTMLElement>('#stLook'), jump = root.querySelector<HTMLElement>('#stJump'), photo = root.querySelector<HTMLElement>('#stPhoto');
16	  const size = CONFIG.stroll.stick.size;
17	  root.style.setProperty('--st-pad', size + 'px');   // đường kính cần gạt lấy từ CONFIG
18	  let padId = -1, cx = 0, cy = 0, dx = 0, dy = 0, r = size / 2;   // cần gạt: con trỏ, tâm (px màn hình, chốt lúc chạm), độ lệch núm
19	  let lookId = -1, lx = 0, ly = 0;                                 // vuốt camera: con trỏ, vị trí trước
20	  let jumpId = -1;
21	  const own = (el: HTMLElement, e: PointerEvent) => { try { el.setPointerCapture(e.pointerId); } catch { /* con trỏ không còn hoạt động (sự kiện giả) */ } };
22	
23	  const knobTo = (x: number, y: number) => { if (knob) knob.style.transform = x === 0 && y === 0 ? '' : `translate(${x}px,${y}px)`; };
24	  const reset = () => { padId = -1; lookId = -1; jumpId = -1; dx = 0; dy = 0; knobTo(0, 0); };
25	
26	  if (pad) {
27	    pad.addEventListener('pointerdown', (e) => {
28	      if (padId >= 0) return;
29	      e.preventDefault();
30	      const b = pad.getBoundingClientRect();
31	      cx = b.left + b.width / 2; cy = b.top + b.height / 2; r = b.width / 2 || size / 2;
32	      padId = e.pointerId; own(pad, e); h.activity();
33	      pad.dispatchEvent(new PointerEvent('pointermove', { pointerId: e.pointerId, clientX: e.clientX, clientY: e.clientY }));   // núm theo ngón ngay lúc chạm
34	    });
35	    pad.addEventListener('pointermove', (e) => {
36	      if (e.pointerId !== padId) return;
37	      dx = e.clientX - cx; dy = e.clientY - cy;
38	      const d = Math.sqrt(dx * dx + dy * dy);
39	      if (d > r) { dx = dx / d * r; dy = dy / d * r; }   // núm không ra khỏi vòng
40	      knobTo(dx, dy); h.activity();
41	    });
42	    const padEnd = (e: PointerEvent) => { if (e.pointerId === padId) { padId = -1; dx = 0; dy = 0; knobTo(0, 0); } };
43	    pad.addEventListener('pointerup', padEnd);
44	    pad.addEventListener('pointercancel', padEnd);
45	    pad.addEventListener('lostpointercapture', padEnd);
46	  }
47	
48	  if (look) {
49	    look.addEventListener('pointerdown', (e) => {
50	      if (lookId >= 0) return;
51	      e.preventDefault();
52	      lookId = e.pointerId; lx = e.clientX; ly = e.clientY; own(look, e); h.activity();
53	    });
54	    look.addEventListener('pointermove', (e) => {
55	      if (e.pointerId !== lookId) return;
56	      h.look(e.clientX - lx, e.clientY - ly); h.activity();
57	      lx = e.clientX; ly = e.clientY;
58	    });
59	    const lookEnd = (e: PointerEvent) => { if (e.pointerId === lookId) lookId = -1; };
60	    look.addEventListener('pointerup', lookEnd);
61	    look.addEventListener('pointercancel', lookEnd);
62	    look.addEventListener('lostpointercapture', lookEnd);
63	  }
64	
65	  if (jump) {
66	    jump.addEventListener('pointerdown', (e) => {
67	      e.preventDefault();
68	      if (jumpId < 0) { jumpId = e.pointerId; own(jump, e); h.jump(); h.activity(); }   // một lần chạm một lần nhảy
69	    });
70	    const jumpEnd = (e: PointerEvent) => { if (e.pointerId === jumpId) jumpId = -1; };
71	    jump.addEventListener('pointerup', jumpEnd);
72	    jump.addEventListener('pointercancel', jumpEnd);
73	    jump.addEventListener('lostpointercapture', jumpEnd);
74	  }
75	
76	  if (photo) photo.addEventListener('click', () => { h.activity(); h.photo(); });   // chuột và chạm đều ra click
77	
78	  window.addEventListener('blur', reset);
79	  document.addEventListener('visibilitychange', () => { if (document.hidden) reset(); });
80	  window.addEventListener('orientationchange', reset);
81	  window.addEventListener('resize', reset);
82	
83	  return {
84	    read(out: StInput): void { if (padId >= 0) stStick(dx, dy, r, out); },
85	    reset
86	  };
87	}
